<script setup lang="ts">
import VProfileTile from './VProfileTile.vue';
export interface AccountManager {name:string;role?:string;avatarUrl?:string;email?:string;phone?:string;bookingUrl?:string;messageUrl?:string;responseTime?:string}
defineProps<{manager?:AccountManager|null;supportHref:string}>();
function safe(value?:string){if(!value)return undefined;try{const u=new URL(value);return u.protocol==='https:'?u.href:undefined;}catch{return undefined;}}
</script>
<template><section class="vx-account-manager" aria-label="Your account manager"><div class="vx-account-manager__heading"><h2>Your account manager</h2><slot name="actions" /></div><template v-if="manager"><VProfileTile :name="manager.name" :subtitle="manager.role" :avatar-url="safe(manager.avatarUrl)"><small v-if="manager.responseTime" class="vx-account-manager__response">{{manager.responseTime}}</small></VProfileTile><p>Here to help you get the most out of your camp workspace.</p><div class="vx-account-manager__contacts"><a v-if="safe(manager.messageUrl)||manager.email" :href="safe(manager.messageUrl)||'mailto:'+manager.email" :target="safe(manager.messageUrl)?'_blank':undefined" rel="noopener noreferrer">Message</a><a v-if="safe(manager.bookingUrl)" :href="safe(manager.bookingUrl)" target="_blank" rel="noopener noreferrer">Book a call ↗</a><a v-if="manager.phone" :href="'tel:'+manager.phone">Call</a></div></template><div v-else class="vx-account-manager__empty"><span aria-hidden="true">✦</span><strong>A person in your corner.</strong><p>Your account manager hasn’t been assigned yet. Our support team can still help.</p></div><a class="vx-account-manager__support" :href="supportHref" target="_blank" rel="noopener noreferrer">Visit support hub ↗</a></section></template>
